     5  /* merge is destructive, the _second_ tree is destroyed */
     6  int igraph_gml_tree_mergedest(igraph_gml_tree_t *t1, igraph_gml_tree_t *t2) {
     7      long int i, n = igraph_vector_ptr_size(&t2->children);
     8      for (i = 0; i < n; i++) {
     9          IGRAPH_CHECK(igraph_vector_ptr_push_back(&t1->names, VECTOR(t2->names)[i]));
    10          IGRAPH_CHECK(igraph_vector_char_push_back(&t1->types, VECTOR(t2->types)[i]));
    11          IGRAPH_CHECK(igraph_vector_ptr_push_back(&t1->children,
    12                       VECTOR(t2->children)[i]));
    13      }
    14
    15      igraph_vector_ptr_destroy(&t2->names);
    16      igraph_vector_char_destroy(&t2->types);
    17      igraph_vector_ptr_destroy(&t2->children);
    18      return 0;
    19  }
