    21  void igraph_gml_tree_destroy(igraph_gml_tree_t *t) {
    22
    23      long int i, n = igraph_vector_ptr_size(&t->children);
    24      for (i = 0; i < n; i++) {
    25          int type = VECTOR(t->types)[i];
    26          switch (type) {
    27          case IGRAPH_I_GML_TREE_TREE:
    28              igraph_gml_tree_destroy(VECTOR(t->children)[i]);
    29              igraph_Free(VECTOR(t->names)[i]);
    30              break;
    31          case IGRAPH_I_GML_TREE_INTEGER:
    32              igraph_Free(VECTOR(t->children)[i]);
    33              igraph_Free(VECTOR(t->names)[i]);
    34              break;
    35          case IGRAPH_I_GML_TREE_REAL:
    36              igraph_Free(VECTOR(t->children)[i]);
    37              igraph_Free(VECTOR(t->names)[i]);
    38              break;
    39          case IGRAPH_I_GML_TREE_STRING:
    40              igraph_Free(VECTOR(t->children)[i]);
    41              igraph_Free(VECTOR(t->names)[i]);
    42              break;
    43          case IGRAPH_I_GML_TREE_DELETED:
    44              break;
    45          }
    46      }
    47      igraph_vector_ptr_destroy(&t->names);
    48      igraph_vector_char_destroy(&t->types);
    49      igraph_vector_ptr_destroy(&t->children);
    50      igraph_Free(t);
    51  }
